class Solution {
  private int[] parent;

  public int[] processQueries(int c, int[][] connections, int[][] queries) {
    parent = new int[c + 1];
    for (int i = 0; i <= c; i++) parent[i] = i;
    for (int[] e : connections) parent[find(e[0])] = find(e[1]);
    // station ids of each grid in ascending order
    Map<Integer, List<Integer>> grids = new HashMap<>();
    for (int i = 1; i <= c; i++) grids.computeIfAbsent(find(i), k -> new ArrayList<>()).add(i);
    Map<Integer, Integer> pointer = new HashMap<>();
    boolean[] offline = new boolean[c + 1];
    List<Integer> out = new ArrayList<>();
    for (int[] q : queries) {
      int x = q[1];
      if (q[0] == 2) {
        offline[x] = true;
        continue;
      }
      if (!offline[x]) {
        out.add(x);
        continue;
      }
      int root = find(x);
      List<Integer> ids = grids.get(root);
      int p = pointer.getOrDefault(root, 0);
      while (p < ids.size() && offline[ids.get(p)]) p++; // stations never come back online
      pointer.put(root, p);
      out.add(p < ids.size() ? ids.get(p) : -1);
    }
    int[] ans = new int[out.size()];
    for (int i = 0; i < ans.length; i++) ans[i] = out.get(i);
    return ans;
  }

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
}
